/**
 * The `tecton` command behind bin/tecton.mjs: the tokenizer, the ranking, the
 * index reader and `run(argv)`. Kept apart from the executable so the tests,
 * the eval (agent-eval/search-eval.mjs) and agent-build.mts import it without
 * running the CLI, and so the executable never has to work out whether it was
 * imported or invoked (which fails under `node --preserve-symlinks-main`).
 *
 * Reads agent/index.json and agent/docs/*.md, generated by
 * `pnpm --filter @tecton/react agent:build`. Plain Node, no dependencies:
 * it ships in the package and runs from an application's node_modules.
 */
import { existsSync, readFileSync } from "node:fs"
import path from "node:path"
import { fileURLToPath } from "node:url"

const PKG_ROOT = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  ".."
)
const AGENT_DIR = path.join(PKG_ROOT, "agent")

// ---------------------------------------------------------------------------
// text
// ---------------------------------------------------------------------------

/**
 * Words that say nothing about which component is meant. `page`, `show`,
 * `display` and `user` are not here: "page header", "show a toast", "user
 * avatar" are real needs. The contraction stumps (`does`, `ca`, `wo`, `did`)
 * are what `doesn't`, `can't`, `won't`, `didn't` leave once `n't` is cut.
 */
export const STOPWORDS = new Set(
  (
    "a an and are as at be but by can do does did ca wo for from has have how i if in into is it its " +
    "of on or so that the their them then there these they this to use used using want we when " +
    "where which with without you your need needs needed make build add let lets should one some " +
    "something thing things component components tecton react ui"
  ).split(" ")
)

/** A consonant doubled by a suffix: `setting` -> `sett` -> `set`. */
const DOUBLED = /([^aeiouylsz])\1$/

/**
 * A light suffix stripper, both sides of the index: "wells"/"well",
 * "menus"/"menu", "warnings"/"warning"/"warn", "settings"/"setting"/"set",
 * "resize"/"resizable", "collapse"/"collapsible". The plural goes first, then
 * `-ing` / `-ed` on what is left (Porter step 1a, then 1b).
 */
export function stem(word) {
  let root = word
  // 1a: plurals
  if (root.length > 4 && root.endsWith("sses")) root = root.slice(0, -2)
  else if (root.length > 4 && root.endsWith("ies"))
    root = `${root.slice(0, -3)}y`
  else if (root.length > 4 && /(ches|shes|xes|zzes)$/.test(root))
    root = root.slice(0, -2)
  else if (root.length > 3 && root.endsWith("s") && !/(ss|is)$/.test(root))
    root = root.slice(0, -1)
  // 1b: -ing / -ed, when a vowel is left in the stem ("string" stays)
  const verb = /^(.{3,}?)(ing|ed)$/.exec(root)
  if (verb && !root.endsWith("eed") && /[aeiouy]/.test(verb[1])) {
    root = verb[1]
    if (DOUBLED.test(root)) root = root.slice(0, -1)
  }
  if (root.length > 7 && /[ai]ble$/.test(root)) root = root.slice(0, -4)
  if (root.length > 4 && root.endsWith("e")) root = root.slice(0, -1)
  return root
}

/**
 * `ScrollArea` -> `Scroll Area ScrollArea`: the words, so the query meets the
 * component's name, and the identifier whole, so `isSelected` still meets the
 * page that spells it out rather than every page that says "select".
 */
function splitCamel(text) {
  return text.replace(
    /\b[A-Za-z0-9]*[a-z0-9][A-Z][A-Za-z0-9]*\b/g,
    (word) =>
      `${word
        .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
        .replace(/([A-Z])([A-Z][a-z])/g, "$1 $2")} ${word}`
  )
}

/**
 * Words of a text: camelCase split (see splitCamel; `camel: false` keeps an
 * identifier whole, which is how the index reads its own prose), contractions
 * and 1-letter scraps dropped, stopwords dropped, stemmed.
 */
export function tokenize(text, { camel = true } = {}) {
  return (camel ? splitCamel(String(text)) : String(text))
    .toLowerCase()
    .replace(/['’](s|re|ve|ll|d|m)\b/g, "")
    .replace(/n['’]t\b/g, "")
    .replace(/[^a-z0-9]+/g, " ")
    .split(" ")
    .filter((word) => word.length > 1 && !STOPWORDS.has(word))
    .map(stem)
}

// ---------------------------------------------------------------------------
// the index
// ---------------------------------------------------------------------------

/** Field weights for BM25F: a name match beats a mention in a Do bullet. */
export const WEIGHTS = { names: 3, routed: 2, useWhen: 1.5, do: 0.6 }
const K1 = 1.2
const B = 0.6
/** Weight of a word that came from synonyms.json rather than from the query. */
const SYNONYM_WEIGHT = 0.7
/**
 * Added to an entry whose name the query spells out ("button group for save
 * and cancel"), per word of the name: the typed name outranks a component that
 * happens to share more of the sentence's other words.
 */
const NAME_BOOST = 2

export function loadIndex(dir = AGENT_DIR) {
  const file = path.join(dir, "index.json")
  if (!existsSync(file)) {
    throw new Error(
      `tecton: ${file} is missing — run \`pnpm --filter @tecton/react agent:build\``
    )
  }
  const index = JSON.parse(readFileSync(file, "utf8"))
  const fields = Object.keys(WEIGHTS)
  const docs = index.entries.map((entry) => {
    const tf = {}
    const length = {}
    for (const field of fields) {
      // The names field is already split (`alert dialog action`); in the prose
      // an identifier stays whole, so `SelectItem` in a Do bullet does not
      // count as one more "select" everywhere.
      const words = tokenize(entry.fields[field] ?? "", { camel: false })
      length[field] = words.length
      const counts = new Map()
      for (const word of words) counts.set(word, (counts.get(word) ?? 0) + 1)
      tf[field] = counts
    }
    const name = entry.kind === "topic" ? [] : tokenize(entry.id)
    return { entry, tf, length, name }
  })
  const avg = {}
  for (const field of fields) {
    avg[field] =
      docs.reduce((sum, doc) => sum + doc.length[field], 0) / docs.length || 1
  }
  const df = new Map()
  for (const doc of docs) {
    const seen = new Set()
    for (const field of fields)
      for (const word of doc.tf[field].keys()) seen.add(word)
    for (const word of seen) df.set(word, (df.get(word) ?? 0) + 1)
  }
  const synonyms = compileSynonyms(index.synonyms ?? {})
  const byKey = new Map()
  for (const entry of index.entries) {
    byKey.set(entry.id.toLowerCase(), entry.id)
    byKey.set(entry.name.toLowerCase(), entry.id)
    for (const name of [...entry.exports, ...(entry.aliases ?? [])]) {
      if (!byKey.has(name.toLowerCase()))
        byKey.set(name.toLowerCase(), entry.id)
    }
  }
  return { ...index, dir, docs, avg, df, synonyms, byKey }
}

/**
 * synonyms.json as `{ words, targets }` rules, both stemmed. A key is one word
 * (`modal`) or a phrase (`pin code`) that must occur in the query in that order.
 */
export function compileSynonyms(synonyms) {
  return Object.entries(synonyms).map(([key, targets]) => ({
    key,
    words: tokenize(key),
    targets: targets.flatMap((target) => tokenize(target)),
  }))
}

/** Whether `words` occurs in `tokens` as a contiguous run. */
function containsRun(tokens, words) {
  if (!words.length || words.length > tokens.length) return false
  outer: for (let at = 0; at + words.length <= tokens.length; at++) {
    for (let offset = 0; offset < words.length; offset++) {
      if (tokens[at + offset] !== words[offset]) continue outer
    }
    return true
  }
  return false
}

/** Query words with their weights: the words typed, then their synonyms. */
function expand(tokens, index, useSynonyms) {
  const terms = new Map()
  for (const word of tokens) terms.set(word, 1)
  if (!useSynonyms) return terms
  for (const rule of index.synonyms) {
    if (!containsRun(tokens, rule.words)) continue
    for (const target of rule.targets) {
      if (!terms.has(target)) terms.set(target, SYNONYM_WEIGHT)
    }
  }
  return terms
}

/**
 * The entry a query names outright — `ScrollArea`, `scroll area`,
 * `scroll-area`, `SelectItem`, `toast` — or null.
 */
export function exactMatch(index, query) {
  const text = String(query).trim()
  if (!text || text.split(/\s+/).length > 3) return null
  return (
    resolveId(index, text) ??
    resolveId(index, text.replace(/\s+/g, "-")) ??
    resolveId(index, text.replace(/\s+/g, ""))
  )
}

/**
 * BM25F over the entry fields, plus a boost for a name the query spells out and
 * rank 1 for an exact id or export. `weights`, `synonyms` and `names` exist for
 * the eval's ablations (agent-eval/search-eval.mjs); the CLI uses the defaults.
 */
export function search(
  index,
  query,
  { limit = 5, weights = WEIGHTS, synonyms = true, names = true } = {}
) {
  const tokens = tokenize(query)
  const terms = expand(tokens, index, synonyms)
  const total = index.docs.length
  const results = []
  for (const doc of index.docs) {
    let score = 0
    for (const [term, weight] of terms) {
      const df = index.df.get(term)
      if (!df) continue
      let tf = 0
      for (const [field, fieldWeight] of Object.entries(weights)) {
        if (!fieldWeight) continue
        const count = doc.tf[field].get(term)
        if (!count) continue
        tf +=
          (fieldWeight * count) /
          (1 - B + (B * doc.length[field]) / index.avg[field])
      }
      if (!tf) continue
      const idf = Math.log(1 + (total - df + 0.5) / (df + 0.5))
      score += weight * idf * ((tf * (K1 + 1)) / (tf + K1))
    }
    if (names && score > 0 && containsRun(tokens, doc.name)) {
      score += NAME_BOOST * doc.name.length
    }
    if (score > 0) results.push({ entry: doc.entry, score })
  }
  results.sort(
    (a, b) => b.score - a.score || a.entry.id.localeCompare(b.entry.id)
  )
  const pinned = names ? exactMatch(index, query) : null
  if (pinned) {
    const at = results.findIndex((result) => result.entry.id === pinned)
    const [hit] =
      at === -1
        ? [
            {
              entry: index.entries.find((entry) => entry.id === pinned),
              score: results[0]?.score ?? 0,
            },
          ]
        : results.splice(at, 1)
    results.unshift(hit)
  }
  return results.slice(0, limit)
}

/**
 * Resolves `alert-dialog`, `AlertDialog`, `AlertDialogAction`, `toast`, a
 * module path (`@tecton/react/components/alert-dialog`) or a docs URL
 * (`https://…/docs/components/alert-dialog/#usage`) to an id.
 */
export function resolveId(index, key) {
  const text = String(key)
    .trim()
    .replace(/[?#].*$/, "")
    .replace(/\/+$/, "")
    .replace(/\.mdx?$/, "")
  const last = text.includes("/") ? text.slice(text.lastIndexOf("/") + 1) : text
  return index.byKey.get(last.toLowerCase()) ?? null
}

/** Levenshtein distance, for "did you mean" on a typo. */
function distance(a, b) {
  let previous = Array.from({ length: b.length + 1 }, (_, at) => at)
  for (let i = 1; i <= a.length; i++) {
    const current = [i]
    for (let j = 1; j <= b.length; j++) {
      current[j] = Math.min(
        previous[j] + 1,
        current[j - 1] + 1,
        previous[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1)
      )
    }
    previous = current
  }
  return previous[b.length]
}

/**
 * Up to `limit` ids for a key that resolved to nothing: the ids, names and
 * exports within a few typos of it (`dropdwn` -> dropdown-menu), then what a
 * search for it finds.
 */
export function suggest(index, key, limit = 3) {
  const typed = String(key).trim().toLowerCase()
  const allowed = Math.max(1, Math.floor(typed.length / 4))
  const near = new Map()
  const consider = (candidate, id) => {
    const cost = distance(typed, candidate)
    if (cost <= allowed && cost < (near.get(id) ?? Infinity)) near.set(id, cost)
  }
  for (const [name, id] of index.byKey) {
    consider(name, id)
    for (const part of name.split("-")) if (part.length > 3) consider(part, id)
  }
  const ids = [...near]
    .sort((a, b) => a[1] - b[1] || a[0].localeCompare(b[0]))
    .map(([id]) => id)
  for (const { entry } of search(index, key, { limit })) {
    if (!ids.includes(entry.id)) ids.push(entry.id)
  }
  return ids.slice(0, limit)
}

export function readDoc(index, id) {
  return readFileSync(path.join(index.dir, "docs", `${id}.md`), "utf8")
    .replace(/\r\n/g, "\n")
    .replace(/^<!--.*-->\n\n/, "")
}

// ---------------------------------------------------------------------------
// output
// ---------------------------------------------------------------------------

function formatTokens(tokens) {
  return tokens >= 1000 ? `${(tokens / 1000).toFixed(1)}k` : String(tokens)
}

function truncate(text, max) {
  const flat = text.replace(/`/g, "").replace(/\s+/g, " ").trim()
  return flat.length > max ? `${flat.slice(0, max - 1)}…` : flat
}

export function renderSearch(query, results) {
  if (!results.length) {
    return `No match for "${query}". Try other words, or \`tecton list\` to browse every component.`
  }
  const lines = []
  results.forEach(({ entry }, at) => {
    const kind = entry.kind === "topic" ? " — topic" : ""
    lines.push(
      `${at + 1}. ${entry.id} — ${entry.name}${kind} — ≈${formatTokens(entry.tokens)} tok`
    )
    for (const line of (entry.import ?? "").split("\n").filter(Boolean)) {
      lines.push(`   ${line}`)
    }
    lines.push(`   ${truncate(entry.summary, 140)}`)
    if (entry.notFor.length) {
      const boundaries = entry.notFor
        .slice(0, 3)
        .map((item) => `${truncate(item.need, 60)} → ${item.id}`)
      lines.push(`   not for: ${boundaries.join("; ")}`)
    }
  })
  lines.push(
    "",
    `Next: tecton docs ${results[0].entry.id}${results[1] ? ` (or ${results[1].entry.id})` : ""}`
  )
  return lines.join("\n")
}

function renderList(entries) {
  return entries
    .map(
      (entry) =>
        `${entry.id} — ${entry.name}${entry.family ? ` [${entry.family}]` : ` [${entry.kind}]`} — ${truncate(entry.summary, 90)}`
    )
    .join("\n")
}

export const HELP = `tecton — look up @tecton/react components

  tecton search <what the UI must do>   ranked components with import and boundaries
  tecton docs <id|Component>[,…]        usage guideline: Use it when, Not for, Do, Don't
  tecton list [--family <name>]         every id with a one-line summary
  tecton rules                          the rules every file follows

Options: --json (every command), --limit <n> (search, default 5)`

// ---------------------------------------------------------------------------
// run
// ---------------------------------------------------------------------------

/** The options each command takes: `true` for a flag, `"value"` for one with a value. */
const OPTIONS = {
  search: { "--json": true, "--limit": "value" },
  docs: { "--json": true },
  rules: { "--json": true },
  list: { "--json": true, "--family": "value" },
}

/**
 * Splits `args` into options and words. `--limit 3` and `--limit=3` both work;
 * an option the command does not take, or one missing its value, is an error.
 */
function parseArgs(command, args) {
  const allowed = OPTIONS[command]
  const options = {}
  const words = []
  for (let at = 0; at < args.length; at++) {
    const arg = args[at]
    if (!arg.startsWith("--")) {
      words.push(arg)
      continue
    }
    const [flag, inline] = arg.split(/=(.*)/s, 2)
    const kind = allowed[flag]
    if (!kind) return { error: `tecton ${command}: unknown option ${flag}` }
    if (kind === true) {
      if (inline !== undefined)
        return { error: `tecton ${command}: ${flag} takes no value` }
      options[flag] = true
      continue
    }
    const value = inline ?? args[++at]
    if (value === undefined || value === "" || value.startsWith("--"))
      return { error: `tecton ${command}: ${flag} needs a value` }
    options[flag] = value
  }
  return { options, words }
}

const fail = (err) => ({ code: 1, out: "", err })
const ok = (out, err = "") => ({ code: 0, out, err })

/**
 * Runs one command line and returns what to print: `out` for stdout, `err` for
 * stderr (usage errors, unknown ids) and the exit code. `index` is loaded on
 * first use, so `tecton --help` works before `agent:build` has run.
 */
export function run(argv, index) {
  const args = [...argv]
  const command = args.shift()

  if (
    !command ||
    command === "help" ||
    command === "--help" ||
    command === "-h"
  ) {
    return ok(HELP)
  }
  if (!OPTIONS[command]) {
    return fail(`tecton: unknown command "${command}"\n\n${HELP}`)
  }
  const parsed = parseArgs(command, args)
  if (parsed.error) return fail(`${parsed.error}\n\n${HELP}`)
  const { options, words } = parsed
  const json = Boolean(options["--json"])
  const loaded = index ?? loadIndex()

  if (command === "search") {
    const limitText = options["--limit"] ?? "5"
    if (!/^[1-9]\d*$/.test(limitText))
      return fail(
        `tecton search: --limit takes a positive whole number, got "${limitText}"`
      )
    const query = words.join(" ").trim()
    if (!query)
      return fail(
        'tecton search: say what the UI must do, e.g. tecton search "confirm before deleting"'
      )
    const results = search(loaded, query, { limit: Number(limitText) })
    if (json) {
      return ok(
        JSON.stringify(
          results.map(({ entry, score }) => ({
            id: entry.id,
            name: entry.name,
            kind: entry.kind,
            import: entry.import,
            summary: entry.summary,
            notFor: entry.notFor,
            tokens: entry.tokens,
            score: Number(score.toFixed(3)),
          })),
          null,
          2
        )
      )
    }
    return ok(renderSearch(query, results))
  }

  if (command === "docs" || command === "rules") {
    const keys =
      command === "rules"
        ? ["rules"]
        : words
            .join(",")
            .split(",")
            .map((key) => key.trim())
            .filter(Boolean)
    if (!keys.length)
      return fail(
        "tecton docs: name one or more ids, e.g. tecton docs select,combobox"
      )
    const found = []
    const misses = []
    for (const key of keys) {
      const id = resolveId(loaded, key)
      if (id) {
        if (!found.some((doc) => doc.id === id))
          found.push({ id, markdown: readDoc(loaded, id).trimEnd() })
        continue
      }
      const guesses = suggest(loaded, key)
      misses.push(
        `No entry "${key}".${guesses.length ? ` Did you mean: ${guesses.join(", ")}?` : ""}`
      )
    }
    const out = json
      ? found.length
        ? JSON.stringify(
            found.map(({ id, markdown }) => {
              const entry = loaded.entries.find((item) => item.id === id)
              return {
                id,
                name: entry?.name,
                kind: entry?.kind,
                import: entry?.import,
                markdown,
              }
            }),
            null,
            2
          )
        : ""
      : found.map((doc) => doc.markdown).join("\n\n---\n\n")
    return { code: misses.length ? 1 : 0, out, err: misses.join("\n") }
  }

  // list
  const family = options["--family"]
  const families = [
    ...new Set(loaded.entries.map((entry) => entry.family).filter(Boolean)),
  ].sort()
  if (family !== undefined && !families.includes(family)) {
    return fail(
      `tecton list: no family "${family}". Families: ${families.join(", ")}`
    )
  }
  const entries = loaded.entries.filter(
    (entry) => !family || entry.family === family
  )
  if (json) {
    return ok(
      JSON.stringify(
        entries.map(({ id, name, kind, family: group, summary }) => ({
          id,
          name,
          kind,
          family: group,
          summary,
        })),
        null,
        2
      )
    )
  }
  return ok(renderList(entries))
}

/** The executable's body: runs `argv`, prints, sets the exit code. */
export function main(argv = process.argv.slice(2)) {
  try {
    const { code, out, err } = run(argv)
    if (out) process.stdout.write(`${out}\n`)
    if (err) process.stderr.write(`${err}\n`)
    process.exitCode = code
  } catch (error) {
    process.stderr.write(`${error.message}\n`)
    process.exitCode = 1
  }
}
